        h.runAtTickTime(20,()->{check(dispenser.isEmpty()&&drops(h).stream().anyMatch(e->e.getItem().is(PSItems.JUNIPER_BOAT.get()))&&level.getEntitiesOfClass(JuniperBoat.class,new AABB(pos).inflate(4)).isEmpty(),"invalid launch surface drops original item instead of spawning boat");h.succeed();});
