    @GameTest(template="empty") public static void chestBoatCapabilitiesSimulateSnapshotAndStayInertAfterRemoval(GameTestHelper h){
        var boat=PSEntities.JUNIPER_CHEST_BOAT.get().create(h.getLevel());boat.setPos(h.absolutePos(POS).getCenter());h.getLevel().addFreshEntity(boat);var optional=boat.getCapability(ForgeCapabilities.ITEM_HANDLER);var handler=optional.orElseThrow(AssertionError::new);var original=cargo();check(handler.getSlots()==27&&handler.insertItem(0,original,true).isEmpty()&&boat.getItem(0).isEmpty(),"native chest inventory simulation does not change cargo");handler.insertItem(0,original,false);var snapshot=handler.getStackInSlot(0);snapshot.getTag().putInt("custom",0);check(ItemStack.matches(original,boat.getItem(0)),"capability reads do not expose mutable cargo storage");boat.remove(Entity.RemovalReason.DISCARDED);check(!optional.isPresent()&&handler.extractItem(0,1,false).isEmpty()&&handler.insertItem(1,new ItemStack(Items.PAPER),false).is(Items.PAPER),"removed chest boat invalidates optional and resolved handler");boat.revive();check(handler.extractItem(0,1,false).isEmpty(),"revival cannot reactivate a capability from the previous entity lifetime");boat.discard();h.succeed();
    }
    @GameTest(template="empty") public static void chestBoatEntitySaveAndNormalDestructionConserveCargo(GameTestHelper h){
        var level=h.getLevel();var pos=h.absolutePos(POS);var p=player(h);var boat=PSEntities.JUNIPER_CHEST_BOAT.get().create(level);boat.setPos(pos.getCenter());boat.setItem(0,cargo());boat.setItem(26,new ItemStack(Items.OAK_PLANKS,7));boat.setCustomName(Component.literal("Juniper cargo"));var saved=new CompoundTag();check(boat.save(saved),"native entity save includes registered id");var loaded=(JuniperChestBoat)EntityType.loadEntityRecursive(saved,level,java.util.function.Function.identity());check(loaded!=null&&ItemStack.matches(loaded.getItem(0),cargo())&&loaded.getItem(26).getCount()==7&&loaded.getDisplayName().getString().equals("Juniper cargo"),"native entity load restores named chest boat and exact cargo NBT");level.addFreshEntity(loaded);loaded.hurt(level.damageSources().playerAttack(p),5);var drops=drops(h);check(loaded.isRemoved()&&drops.stream().filter(e->e.getItem().is(PSItems.JUNIPER_CHEST_BOAT.get())).mapToInt(e->e.getItem().getCount()).sum()==1&&drops.stream().anyMatch(e->ItemStack.matches(e.getItem(),cargo()))&&drops.stream().anyMatch(e->e.getItem().is(Items.OAK_PLANKS)&&e.getItem().getCount()==7),"normal native attack drops one combined boat and exact cargo once; oak cargo keeps its identity");drops.forEach(Entity::discard);h.succeed();
    }
    @GameTest(template="juniper",timeoutTicks=100) public static void nativeBoatFallBreakDropsJuniperHullMaterials(GameTestHelper h){
        List<JuniperBoat> own=new ArrayList<>();List<Boat> vanilla=new ArrayList<>();int[] heights={4,5,8,13,14};for(var floor:BlockPos.betweenClosed(new BlockPos(0,0,0),new BlockPos(15,0,15)))h.setBlock(floor,Blocks.GRASS_BLOCK);
        for(int index=0;index<heights.length;index++){var at=h.absolutePos(new BlockPos(1+index*3,heights[index],4));var custom=PSEntities.JUNIPER_BOAT.get().create(h.getLevel());custom.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);h.getLevel().addFreshEntity(custom);own.add(custom);var control=new Boat(h.getLevel(),at.getX()+.5,at.getY(),at.getZ()+7.5);h.getLevel().addFreshEntity(control);vanilla.add(control);}
        h.runAtTickTime(65,()->{int broken=0;for(int index=0;index<own.size();index++){var boat=own.get(index);var control=vanilla.get(index);check(boat.isRemoved()==control.isRemoved(),"juniper and native oak boats share actual fall behavior at height "+heights[index]);if(!control.isRemoved())continue;broken++;var items=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(boat.blockPosition()).inflate(1.4));check(items.stream().filter(e->e.getItem().is(PSItems.JUNIPER_PLANKS.get())).mapToInt(e->e.getItem().getCount()).sum()==3&&items.stream().filter(e->e.getItem().is(Items.STICK)).mapToInt(e->e.getItem().getCount()).sum()==2&&items.stream().noneMatch(e->e.getItem().is(Items.OAK_PLANKS)),"real native fall destruction drops three juniper planks and two sticks");items.forEach(Entity::discard);}check(broken>0,"native control fall diagnostics="+vanilla.stream().map(b->b.position()+" velocity="+b.getDeltaMovement()+" fall="+b.fallDistance+" removed="+b.isRemoved()+" below="+h.getLevel().getBlockState(b.blockPosition().below())).toList());h.succeed();});
    }
    @GameTest(template="empty",timeoutTicks=200) public static void juniperFruitRecipeCompletesThroughNormalMashTubTicks(GameTestHelper h){
        var center=new BlockPos(2,1,2);h.setBlock(center,PSBlocks.MASH_TUB.get());for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)if(dx!=0||dz!=0)h.setBlock(center.offset(dx,0,dz),MashTubBlock.wallState(dx,dz));var vat=(MashTubBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(center));vat.getTank().replace(new FluidStack(Fluids.WATER,1000));for(var item:List.of(PSItems.JUNIPER_BERRIES.get(),PSItems.JUNIPER_BERRIES.get(),PSItems.JUNIPER_BERRIES.get(),PSItems.JUNIPER_BERRIES.get(),Items.SUGAR,PSItems.WINE_GRAPES.get(),PSItems.WINE_GRAPES.get(),Items.WHEAT))check(vat.addIngredient(new ItemStack(item)),"real registered fruit/grape batch accepts source ingredient");check(vat.isStewing(),"complete juniper recipe starts native mash process");h.runAtTickTime(160,()->{check(!vat.isStewing()&&vat.getTank().getFluid().getFluid()==PSFluids.JUNIPER.get()&&vat.getTank().getFluidAmount()==1000,"normal native mash ticks yield full juniper fluid without altering amount");h.succeed();});
    }
    @GameTest(template="empty") public static void berriesAndGrapesRetainQuickEatingAndCreativeStacks(GameTestHelper h){
        var p=player(h);for(var item:List.of(PSItems.JUNIPER_BERRIES.get(),PSItems.WINE_GRAPES.get())){p.setGameMode(GameType.SURVIVAL);p.getFoodData().setFoodLevel(18);p.getFoodData().setSaturation(0);var food=new ItemStack(item,3);check(item.getUseDuration(food)==15,"source fruit eats in fifteen ticks");var result=item.finishUsingItem(food,h.getLevel(),p);check(result.getCount()==2&&p.getFoodData().getFoodLevel()==19&&p.getFoodData().getSaturationLevel()==1,"native quick fruit food gives source nutrition/saturation");p.setGameMode(GameType.CREATIVE);food=new ItemStack(item,3);food.setHoverName(Component.literal("Reserve fruit"));var snapshot=food.copy();check(ItemStack.matches(snapshot,item.finishUsingItem(food,h.getLevel(),p)),"creative quick fruit consumption keeps exact stack");}h.succeed();
    }
